import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:go_router/go_router.dart';
import 'package:collega_app/core/ui/theme/cg_theme.dart';

void main() {
  testWidgets('push in shell: transparent pages overlap during transition', (tester) async {
    final router = GoRouter(initialLocation: '/colleges', routes: [
      ShellRoute(builder: (c, s, child) => ColoredBox(color: const Color(0xFFECEAE3), child: child), routes: [
        GoRoute(path: '/colleges', builder: (_, __) => const Align(alignment: Alignment.topLeft, child: Text('LIST', textDirection: TextDirection.ltr))),
        GoRoute(path: '/colleges/1', builder: (_, __) => const Align(alignment: Alignment.topLeft, child: Text('DETAIL', textDirection: TextDirection.ltr))),
      ]),
    ]);
    await tester.pumpWidget(MaterialApp.router(theme: buildCgMaterialTheme(CgThemeData.light), routerConfig: router));
    await tester.pumpAndSettle();
    router.push('/colleges/1');
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 150));
    // ignore: avoid_print
    print('LIST x=${tester.getTopLeft(find.text('LIST')).dx} DETAIL x=${tester.getTopLeft(find.text('DETAIL')).dx}');
    await tester.pumpAndSettle();
  });
}
